C={'T':T,'S':S};A=[(k,d) for k in C for d in [-1,1]]
def mp(p,a):
 cy=C[a[0]]
 return cy[(cy.index(p)+a[1])%len(cy)] if p in cy else p
def can(ps):return tuple(sorted(ps))
